from itertools import combinations
S={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# 2x2 squares and L triominoes, identify color by missing corner in 2x2 bbox: color 2 missing UL; 3 missing UR? from demos map determine below
pieces=[]
for r in range(7):
 for c in range(7):
  sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if sq<=S: pieces.append((sq,1,'square'))
  for miss in [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]:
   l={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}-{miss}
   if l<=S: pieces.append((l,None,miss))
sol=[]
def rec(rem, chosen):
 if not rem:
  sol.append(chosen); return
 x=min(rem)
 for p in pieces:
  if x in p[0] and p[0]<=rem:
   rec(rem-p[0],chosen+[p])
rec(S,[])
print('solutions',len(sol))
for ss in sol[:10]: print([(sorted(p[0]),p[1],p[2]) for p in ss])
